<?php require dirname(__DIR__).'/config/config.php'; require dirname(__DIR__).'/vendor/autoload.php'; use App\Helpers\Security; use App\Helpers\Audit; $u=Security::requireRole(['administrador','gerente','operador']); if($_SERVER['REQUEST_METHOD']==='POST'){Security::checkCsrf($_POST['csrf']??null);$s=db()->prepare('INSERT INTO cacambas(numero,tipo,status,localizacao,observacao) VALUES(?,?,?,?,?)');$s->execute([trim($_POST['numero']),$_POST['tipo'],$_POST['status']??'disponivel',trim($_POST['localizacao']??''),trim($_POST['observacao']??'')]);Audit::log('Cadastro de caçamba','cacambas',(int)db()->lastInsertId());header('Location: cacambas.php');exit;}$rows=db()->query('SELECT * FROM cacambas ORDER BY numero')->fetchAll();?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Caçambas</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="css/app.css"></head><body><div class="container py-4"><h1>Caçambas</h1><a href="dashboard.php">← Dashboard</a><div class="card p-3 my-4"><form method="post" class="row g-2"><input type="hidden" name="csrf" value="<?=Security::csrf()?>"><div class="col-md-2"><input class="form-control" name="numero" placeholder="Número" required></div><div class="col-md-2"><select class="form-select" name="tipo"><option value="3m3">3m³</option><option value="4m3">4m³</option><option value="5m3">5m³</option><option value="7m3">7m³</option></select></div><div class="col-md-2"><select class="form-select" name="status"><option value="disponivel">Disponível</option><option value="em_uso">Em uso</option><option value="manutencao">Manutenção</option><option value="inativa">Inativa</option></select></div><div class="col-md-3"><input class="form-control" name="localizacao" placeholder="Localização"></div><div class="col-md-2"><input class="form-control" name="observacao" placeholder="Observação"></div><div class="col-md-1"><button class="btn btn-primary w-100">Salvar</button></div></form></div><table class="table table-striped"><thead><tr><th>Número</th><th>Tipo</th><th>Status</th><th>Localização</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=Security::e($r['numero'])?></td><td><?=Security::e($r['tipo'])?></td><td><?=Security::e($r['status'])?></td><td><?=Security::e($r['localizacao'])?></td></tr><?php endforeach;?></tbody></table></div></body></html>
